import{_ as e,o as l,c as a,b6 as d}from"./chunks/framework.COUcLbTA.js";const x=JSON.parse('{"title":"项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/guide/introduction.md","filePath":"zh-cn/guide/introduction.md"}'),i={name:"zh-cn/guide/introduction.md"};function n(s,t,r,g,h,f){return l(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to “项目介绍”">​</a></h1><p>2025年，被很多人视为AI编程的元年。越来越多的人开始用AI写代码，但往往做出来的还停留在玩具层面——不知道如何用Vibe Coding组织开发流程，不知道该选哪些工具，更不清楚从原型到上线中间还差哪些关键步骤。</p><p>我们采用循序渐进的<strong>三阶段实战路径</strong>：新手入门阶段通过小游戏快速上手AI编程，第一阶段掌握Vibe Coding工作方式并完成Web应用原型，第二阶段学习全栈开发与部署上线，第三阶段构建跨平台复杂应用。</p><p>每个阶段都配有完整项目实战，让你在真实挑战中从玩具走向产品，最终具备<strong>将任何想法落地为可用应用</strong>的能力。</p><p>我们相信，掌握Vibe Coding并配合系统化训练，你一个人就能成为<strong>集前后端开发、AI能力集成、产品设计于一身的全能开发者</strong>。</p><p>本项目主要面向三类学习者：</p><ul><li><strong>新手（普通人 / 产品与运营侧）</strong>：帮助非技术背景角色和入门学习者听懂关键概念，完成第一个 AI 小工具或产品原型。</li><li><strong>初中级开发者（有一定基础的学生和开发者）</strong>：系统掌握 vibe coding 与原生 AI 应用开发。</li><li><strong>高级开发者（公司与初创、开源与独立开发者）</strong>：支持团队和个人快速搭建、验证与迭代原生 AI 应用。</li></ul><h2 id="📖-内容导航" tabindex="-1">📖 内容导航 <a class="header-anchor" href="#📖-内容导航" aria-label="Permalink to “📖 内容导航”">​</a></h2><h3 id="总附录" tabindex="-1">总附录 <a class="header-anchor" href="#总附录" aria-label="Permalink to “总附录”">​</a></h3><p><a href="/easy-vibe/zh-cn/appendix/8-artificial-intelligence/ai-capability-dictionary.html">AI 能力词典：常见 AI 核心概念与名词、场景解释</a></p><h3 id="零、幼儿园" tabindex="-1">零、幼儿园 <a class="header-anchor" href="#零、幼儿园" aria-label="Permalink to “零、幼儿园”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">章节</th><th style="text-align:left;">关键内容</th><th style="text-align:left;">状态</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe/zh-cn/stage-1/learning-map/">新手入门：学习地图</a></td><td style="text-align:left;">整体学习路径导览</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe/zh-cn/stage-1/ai-capabilities-through-games/">新手入门：AI 时代，会说话就会编程</a></td><td style="text-align:left;">通过贪吃蛇等案例初步感受 AI 编程的能力</td><td style="text-align:left;">✅</td></tr></tbody></table><h3 id="一、ai-产品经理" tabindex="-1">一、AI 产品经理 <a class="header-anchor" href="#一、ai-产品经理" aria-label="Permalink to “一、AI 产品经理”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">章节</th><th style="text-align:left;">关键内容</th><th style="text-align:left;">状态</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe/zh-cn/stage-1/introduction-to-ai-ide/">初级二：认识 AI IDE 工具</a></td><td style="text-align:left;">学会使用 IDE，掌握界面结构和高效提示方式</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe/zh-cn/stage-1/building-prototype/">初级三：动手做出原型</a></td><td style="text-align:left;">从产品分析拆解，到多页面产品原型实现的完整闭环</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe/zh-cn/stage-1/integrating-ai-capabilities/">初级四：给原型加上 AI 能力</a></td><td style="text-align:left;">理解并完成常见 AI 能力（文本图片视频）的 API 接入</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe/zh-cn/stage-1/complete-project-practice/">初级五：完整项目实战</a></td><td style="text-align:left;">模拟真实场景、接受用户反馈迭代并完成项目展示（含大作业）</td><td style="text-align:left;">✅</td></tr></tbody></table><h4 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to “附录”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">章节</th><th style="text-align:left;">关键内容</th><th style="text-align:left;">状态</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe/zh-cn/stage-1/appendix-a-product-thinking/">附录A：产品思维补充</a></td><td style="text-align:left;">从想法评估到需求拆解与 MVP 的产品思维框架</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe/zh-cn/stage-1/appendix-b-common-errors/">附录B：常见报错及解决方案</a></td><td style="text-align:left;">vibe coding 中的常见错误及排查方法</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe/zh-cn/stage-1/appendix-idea-sources/">附录：从哪里找点子</a></td><td style="text-align:left;">从参考应用、趋势和 VC 清单里收出细分方向</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe/zh-cn/stage-1/appendix-double-diamond/">附录：双钻模型</a></td><td style="text-align:left;">理解先定义问题，再展开方案设计的完整节奏</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe/zh-cn/stage-1/appendix-jobs-to-be-done/">附录：Jobs to Be Done</a></td><td style="text-align:left;">用 JTBD 方法看清用户真正想完成的事</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe/zh-cn/stage-1/appendix-mom-test/">附录：The Mom Test 用户访谈法</a></td><td style="text-align:left;">通过用户访谈验证需求的调研方法</td><td style="text-align:left;">✅</td></tr></tbody></table><h3 id="二、初中级开发工程师" tabindex="-1">二、初中级开发工程师 <a class="header-anchor" href="#二、初中级开发工程师" aria-label="Permalink to “二、初中级开发工程师”">​</a></h3><h4 id="前端部分" tabindex="-1">前端部分 <a class="header-anchor" href="#前端部分" aria-label="Permalink to “前端部分”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">章节</th><th style="text-align:left;">关键内容</th><th style="text-align:left;">状态</th></tr></thead><tbody><tr><td style="text-align:left;">使用 lovart 生产素材</td><td style="text-align:left;">学会用 lovart 批量生成人物、场景等视觉素材，为 UI 设计和前端开发提供素材基础</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Figma 与 MasterGo 入门</td><td style="text-align:left;">用设计工具梳理信息架构和页面结构，为前端实现打基础</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">构建第一个现代应用程序-UI 设计</td><td style="text-align:left;">基于设计稿完成组件化界面，实现从设计到代码的第一条链路</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">参考 UI 设计规范设计页面和按钮</td><td style="text-align:left;">学习用主流设计规范组织页面结构、按钮层级，并借助 AI 生成设计方案</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe/zh-cn/stage-2/frontend/hogwarts-portraits/">一起做霍格沃茨画像</a></td><td style="text-align:left;">从 0 到 1 做出接入 AI 能力的前端应用，串联设计与开发</td><td style="text-align:left;">🚧</td></tr></tbody></table><h4 id="后端开发部分" tabindex="-1">后端开发部分 <a class="header-anchor" href="#后端开发部分" aria-label="Permalink to “后端开发部分”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">章节</th><th style="text-align:left;">关键内容</th><th style="text-align:left;">状态</th></tr></thead><tbody><tr><td style="text-align:left;">什么是 API</td><td style="text-align:left;">理解 HTTP 接口与请求响应模型，为后端集成与联调做准备</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe/zh-cn/stage-2/backend/database-supabase/">从数据库到 Supabase</a></td><td style="text-align:left;">在 Supabase 上落地数据库和 API，打通数据模型与前端页面</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">大模型辅助编写接口代码与接口文档</td><td style="text-align:left;">用大模型协助生成接口与数据库文档及代码，实现可读可测的后端</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Git 工作流与 Zeabur 部署</td><td style="text-align:left;">在 Git 工作流中管理代码，并将应用部署到 Zeabur 上线</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">现代 CLI 开发工具</td><td style="text-align:left;">使用 CLI 类 AI 编程工具加速开发与调试，形成个人工程化工作流</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">如何集成 stripe 等收费系统</td><td style="text-align:left;">接入支付系统，完成收费链路与基础结算流程</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">构建第一个现代应用程序-全栈应用</td><td style="text-align:left;">综合前端、后端与支付模块，完成可上线的全栈 Web 应用</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">现代前端组件库 + Trae 实战</td><td style="text-align:left;">使用现代前端组件库与 Trae，独立完成可登录注册并支持收费的产品</td><td style="text-align:left;">🚧</td></tr></tbody></table><h4 id="ai-能力附录" tabindex="-1">AI 能力附录 <a class="header-anchor" href="#ai-能力附录" aria-label="Permalink to “AI 能力附录”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">章节</th><th style="text-align:left;">关键内容</th><th style="text-align:left;">状态</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe/zh-cn/stage-2/ai-capabilities/dify-knowledge-base/">Dify 入门与知识库集成</a></td><td style="text-align:left;">用 Dify Workflow 与基础 RAG 搭建工具类产品，为后续应用升级打样</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">学会查询 AI 词典与集成多模态 API</td><td style="text-align:left;">学会查找合适的模型与 API，并把文本、图像等多模态能力接入产品</td><td style="text-align:left;">🚧</td></tr></tbody></table><h3 id="三、高级开发工程师" tabindex="-1">三、高级开发工程师 <a class="header-anchor" href="#三、高级开发工程师" aria-label="Permalink to “三、高级开发工程师”">​</a></h3>',24)])])}const o=e(i,[["render",n]]);export{x as __pageData,o as default};
